#!/usr/bin/env python3
import socket, sys, time

HOST = '127.0.0.1'
PORT = 5560

def connect():
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.settimeout(3)
    s.connect((HOST, PORT))
    return s

def read_all(s, timeout=2.0):
    s.settimeout(timeout)
    buf = b''
    while True:
        try:
            d = s.recv(4096)
            if not d:
                break
            buf += d
        except socket.timeout:
            break
        except Exception:
            break
    return buf

def main():
    mode = sys.argv[1] if len(sys.argv) > 1 else 'read'
    s = connect()
    if mode == 'read':
        time.sleep(1.0)
        out = read_all(s, float(sys.argv[2]) if len(sys.argv) > 2 else 3.0)
        sys.stdout.buffer.write(out)
    elif mode == 'send':
        cmd = sys.argv[2]
        wait = float(sys.argv[3]) if len(sys.argv) > 3 else 2.0
        s.sendall((cmd + '\n').encode())
        time.sleep(1.0)
        out = read_all(s, wait)
        sys.stdout.buffer.write(out)
    s.close()

if __name__ == '__main__':
    main()

