#!/usr/bin/env python3
import socket, sys, time

HOST = '127.0.0.1'
PORT = 5560

def connect():
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.settimeout(2)
    s.connect((HOST, PORT))
    return s

def read_for(s, dur):
    """Read for a FIXED wall-clock duration, regardless of data flow."""
    s.setblocking(False)
    buf = b''
    end = time.time() + dur
    while time.time() < end:
        try:
            d = s.recv(65536)
            if d:
                buf += d
        except BlockingIOError:
            time.sleep(0.02)
        except Exception:
            break
    return buf

def main():
    mode = sys.argv[1] if len(sys.argv) > 1 else 'read'
    s = connect()
    if mode == 'send':
        cmd = sys.argv[2]
        dur = float(sys.argv[3]) if len(sys.argv) > 3 else 3.0
        s.sendall((cmd + '\n').encode())
        out = read_for(s, dur)
        sys.stdout.buffer.write(out)
    elif mode == 'read':
        dur = float(sys.argv[2]) if len(sys.argv) > 2 else 3.0
        out = read_for(s, dur)
        sys.stdout.buffer.write(out)
    s.close()

if __name__ == '__main__':
    main()

