463	audio_capture_t* audio_capture_open(const char* dev_path,
464	    unsigned int sample_rate, unsigned int channels,
465	    unsigned int bits_per_sample)
466	{
467	    if (s_active_capture) {
468	        syslog(LOG_WARNING, "[%s] force closing stale capture\n", TAG);
469	        audio_capture_close(s_active_capture);
470	        usleep(100000);
471	    }
472	
473	    audio_capture_t* cap = calloc(1, sizeof(*cap));
474	    if (!cap) {
475	        return NULL;
476	    }
477	
478	    int ret = -ENOTSUP;
479	
480	    /* Try the portable media_recorder backend FIRST.  On openvela targets
481	     * with a media server (e.g. the goldfish emulator) the media framework
482	     * correctly drives the virtio-snd capture device through the full
483	     * NuttX audio buffer dance.  On devices without a media server (e.g.
484	     * BK7258) media_recorder_open() resolves to a weak stub returning NULL
485	     * immediately, so we fall through to the direct backends below. */
486	    ret = open_media_recorder_capture(cap, sample_rate, channels,
487	        bits_per_sample);
