499	            syslog(LOG_WARNING,
500	                "[%s] NuttX audio capture unavailable (%d), trying next backend\n",
501	                TAG, ret);
502	        }
503	    }
504	#else
505	    (void)dev_path;
506	#endif
507	
508	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
509	    if (ret < 0) {
510	        ret = open_alsa_capture(cap, dev_path, sample_rate, channels,
511	            bits_per_sample);
