610	int audio_capture_read(audio_capture_t* cap, void* buf, size_t len)
611	{
612	    if (!cap || !buf || len == 0) {
613	        return -EINVAL;
614	    }
615	
616	    switch (cap->backend) {
617	    case AUDIO_CAPTURE_BACKEND_NUTTX: {
618	#ifdef CONFIG_AI_AGENT_AUDIO_NUTTX_DIRECT
619	        ssize_t n;
620	
621	        if (cap->handle.fd < 0) {
622	            return -EINVAL;
623	        }
624	
625	        n = read(cap->handle.fd, buf, len);
626	        if (n < 0) {
627	            return -errno;
628	        }
629	
630	        if (n > 0 && cap->bits_per_sample == 16) {
631	            apply_capture_gain(buf, (size_t)n);
632	        }
633	
634	        return (int)n;
635	#else
636	        return -ENOTSUP;
637	#endif
638	    }
639	
640	    case AUDIO_CAPTURE_BACKEND_ALSA: {
641	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
642	        snd_pcm_uframes_t frames;
643	        int nframes;
644	        size_t out_len;
645	
646	        if (!cap->handle.pcm || cap->out_frame_bytes == 0) {
647	            return -EINVAL;
648	        }
649	
650	        frames = len / cap->out_frame_bytes;
651	        if (frames == 0) {
652	            return -EINVAL;
653	        }
654	
655	        if (cap->hw_channels == cap->requested_channels) {
656	            nframes = alsa_read_frames(cap, buf, frames);
657	            if (nframes <= 0) {
658	                return nframes;
659	            }
660	
661	            out_len = (size_t)nframes * cap->out_frame_bytes;
662	            if (cap->bits_per_sample == 16) {
663	                apply_capture_gain(buf, out_len);
664	            }
665	            return (int)out_len;
666	        }
667	
668	        if (cap->bits_per_sample != 16 || cap->requested_channels != 1) {
669	            return -ENOTSUP;
670	        }
671	
672	        if (ensure_scratch_capacity(cap, frames * cap->hw_frame_bytes) < 0) {
673	            return -ENOMEM;
674	        }
675	
676	        nframes = alsa_read_frames(cap, cap->scratch, frames);
677	        if (nframes <= 0) {
678	            return nframes;
679	        }
680	
681	        downmix_interleaved_s16_to_mono(cap, buf, cap->scratch,
682	            (size_t)nframes);
683	        out_len = (size_t)nframes * cap->out_frame_bytes;
684	        apply_capture_gain(buf, out_len);
685	        return (int)out_len;
686	#else
687	        return -ENOTSUP;
688	#endif
689	    }
690	
691	    case AUDIO_CAPTURE_BACKEND_MEDIA_RECORDER: {
692	        ssize_t n;
693	
694	        if (!cap->handle.recorder) {
695	            return -EINVAL;
696	        }
697	
698	        n = media_recorder_read_data(cap->handle.recorder, buf, len);
699	        if (n > 0 && cap->bits_per_sample == 16) {
700	            apply_capture_gain(buf, (size_t)n);
701	        }
702	
703	        return (int)n;
704	    }
705	
706	    default:
707	        return -EINVAL;
708	    }
709	}
