730	#endif
731	
732	    case AUDIO_CAPTURE_BACKEND_ALSA:
733	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
734	        if (cap->handle.pcm && cap->started) {
735	            int ret = snd_vela_pcm_drop(cap->handle.pcm);
736	            cap->started = 0;
737	            return ret;
738	        }
739	        return 0;
740	#else
741	        return -ENOTSUP;
742	#endif
743	
744	    case AUDIO_CAPTURE_BACKEND_MEDIA_RECORDER:
745	        if (cap->handle.recorder) {
