758	void audio_capture_close(audio_capture_t* cap)
759	{
760	    if (!cap) {
761	        return;
762	    }
763	
764	    switch (cap->backend) {
765	    case AUDIO_CAPTURE_BACKEND_NUTTX:
766	#ifdef CONFIG_AI_AGENT_AUDIO_NUTTX_DIRECT
767	        if (cap->handle.fd >= 0) {
768	            if (cap->started) {
769	                ioctl(cap->handle.fd, AUDIOIOC_STOP, 0);
770	                cap->started = 0;
771	            }
772	            close(cap->handle.fd);
773	            cap->handle.fd = -1;
774	        }
775	#endif
776	        break;
