778	    case AUDIO_CAPTURE_BACKEND_ALSA:
779	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
780	        if (cap->handle.pcm) {
781	            if (cap->started) {
782	                snd_vela_pcm_drop(cap->handle.pcm);
783	            }
784	            snd_vela_pcm_close(cap->handle.pcm);
785	            cap->handle.pcm = NULL;
786	        }
787	        free(cap->scratch);
788	        cap->scratch = NULL;
789	        cap->scratch_size = 0;
790	#endif
791	        break;
792	
793	    case AUDIO_CAPTURE_BACKEND_MEDIA_RECORDER:
794	        if (cap->handle.recorder) {
