#!/usr/bin/env python3
"""Persistent bidirectional serial bridge to qemu tcp:5560.

Reads guest output -> appends to /tmp/serial.log
Reads commands from FIFO /tmp/serial.in -> sends to guest
Reconnects on disconnect. Holds the connection so `nowait` boot
output is not lost.
"""
import os, socket, select, time, sys

HOST, PORT = '127.0.0.1', 5560
LOG = '/tmp/serial.log'
FIFO = '/tmp/serial.in'

def connect():
    while True:
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.settimeout(1)
            s.connect((HOST, PORT))
            return s
        except Exception:
            time.sleep(0.5)

def main():
    # truncate log each run
    open(LOG, 'wb').close()
    if not os.path.exists(FIFO):
        os.mkfifo(FIFO)
    # open fifo read end (nonblocking, keep open)
    fifo_fd = os.open(FIFO, os.O_RDONLY | os.O_NONBLOCK)

    logf = open(LOG, 'ab', buffering=0)
    s = connect()
    logf.write(('=== connected to %s:%d ===\n' % (HOST, PORT)).encode())

    while True:
        try:
            r, _, _ = select.select([s, fifo_fd], [], [], 1.0)
            if s in r:
                d = s.recv(65536)
                if not d:
                    logf.write(b'\n=== [disconnected] reconnecting ===\n')
                    s.close()
                    s = connect()
                    logf.write(b'=== [reconnected] ===\n')
                    continue
                logf.write(d)
            if fifo_fd in r:
                d = os.read(fifo_fd, 65536)
                if d:
                    s.sendall(d)
        except Exception as e:
            logf.write(('\n=== [error] %s ===\n' % e).encode())
            time.sleep(0.5)
            try:
                s.close()
            except Exception:
                pass
            s = connect()

if __name__ == '__main__':
    main()
